"""Optional on-demand MiniDLNA integration."""
import json as _media_json

def media_server_action(action,settings=None):
    if action not in ('status','install','save','start','stop','restart','rescan'):
        raise ValueError('Unsupported media action')
    result=privileged_command('pinas-media-server',action,
        payload=_media_json.dumps(settings) if settings is not None else None,
        timeout=240 if action=='install' else 45)
    if result.returncode:raise RuntimeError((result.stderr.strip() or 'Media server helper failed')[-700:])
    return _media_json.loads(result.stdout)

MEDIA_SERVER_HELPER = "#!/usr/bin/env python3\nimport json,os,pathlib,re,subprocess,sys,tempfile\nCONF=pathlib.Path('/etc/minidlna.conf')\nBOOL={'inotify','strict_dlna','enable_tivo','merge_media_dirs','enable_subtitles'}\nTEXT={'friendly_name','model_name','model_number','serial','uuid','presentation_url','album_art_names','force_sort_criteria','log_level','network_interface','tivo_discovery','root_container'}\nINT={'port':(1024,65535),'notify_interval':(30,86400),'max_connections':(1,100)}\nALLOWED=BOOL|TEXT|set(INT)|{'media_dir'}\ndef run(args,timeout=35,env=None):\n    return subprocess.run(args,capture_output=True,text=True,check=True,timeout=timeout,env=env)\ndef installed():\n    p=subprocess.run(['/usr/bin/dpkg-query','-W','-f=$'+'{Status}','minidlna'],capture_output=True,text=True,timeout=8)\n    return p.returncode==0 and p.stdout.strip()=='install ok installed'\ndef active():\n    p=subprocess.run(['/usr/bin/systemctl','is-active','minidlna.service'],capture_output=True,text=True,timeout=8)\n    return p.stdout.strip() if p.returncode==0 else 'inactive'\ndef settings():\n    result={}\n    if CONF.is_file():\n        for line in CONF.read_text().splitlines():\n            line=line.strip()\n            if not line or line.startswith('#') or '=' not in line:continue\n            key,val=line.split('=',1);key=key.strip()\n            if key=='media_dir':result.setdefault(key,[]).append(val.strip())\n            elif key in ALLOWED:result[key]=val.strip()\n    return result\ndef status():\n    present=installed()\n    print(json.dumps({'ok':True,'installed':present,'state':active() if present else 'not-installed','settings':settings() if present else {},'service':'minidlna.service'}))\ndef safe_path(value):\n    if not isinstance(value,str) or len(value)>320 or not value.startswith('/mnt/pinas/'):raise ValueError('Select a PiNAS media folder')\n    p=pathlib.Path(value)\n    if '..' in p.parts or any(x.is_symlink() for x in (p,*p.parents)) or not p.is_dir():raise ValueError('Invalid media folder')\n    mount=run(['/usr/bin/findmnt','-n','-o','TARGET','--target',value]).stdout.strip()\n    if pathlib.Path(mount).parent!=pathlib.Path('/mnt/pinas') or not p.resolve().is_relative_to(pathlib.Path(mount).resolve()):\n        raise ValueError('Media folder is not on a mounted PiNAS volume')\n    return value\ndef validate(data):\n    if not isinstance(data,dict) or set(data)-ALLOWED:raise ValueError('Unknown setting')\n    out={}\n    for key,val in data.items():\n        if key=='media_dir':\n            if not isinstance(val,list) or len(val)>16:raise ValueError('Maximum 16 media folders')\n            folders=[]\n            for entry in val:\n                if not isinstance(entry,dict) or set(entry)-{'path','type'} or entry.get('type') not in ('','A','V','P'):\n                    raise ValueError('Invalid media folder entry')\n                folders.append((entry['type']+',' if entry['type'] else '')+safe_path(entry.get('path')))\n            out[key]=list(dict.fromkeys(folders))\n        elif key in BOOL:\n            if type(val) is not bool:raise ValueError('Invalid '+key)\n            out[key]='yes' if val else 'no'\n        elif key in INT:\n            low,high=INT[key]\n            if type(val) is not int or not low<=val<=high:raise ValueError('Invalid '+key)\n            out[key]=str(val)\n        else:\n            if not isinstance(val,str) or len(val)>180 or any(c in val for c in '\\n\\r#'):raise ValueError('Invalid '+key)\n            if key=='friendly_name' and not val.strip():raise ValueError('Server name required')\n            if key=='network_interface' and val and not re.fullmatch(r'[a-zA-Z0-9_.-]{1,20}(,[a-zA-Z0-9_.-]{1,20}){0,5}',val):raise ValueError('Invalid network interface')\n            if key=='root_container' and val not in ('','.', 'B','M','V','P'):raise ValueError('Invalid root container')\n            if key=='tivo_discovery' and val not in ('','bonjour','beacon'):raise ValueError('Invalid TiVo discovery')\n            out[key]=val\n    return out\ndef atomic(content):\n    fd,tmp=tempfile.mkstemp(prefix='.pinas-minidlna-',dir='/etc')\n    try:\n        os.fchmod(fd,0o644)\n        with os.fdopen(fd,'w') as f:f.write(content);f.flush();os.fsync(f.fileno())\n        os.replace(tmp,CONF)\n    finally:\n        if os.path.exists(tmp):os.unlink(tmp)\ndef save(data):\n    if not installed() or not CONF.is_file():raise ValueError('MiniDLNA unavailable')\n    changes=validate(data);before=CONF.read_text()\n    lines=[]\n    for line in before.splitlines(keepends=True):\n        match=re.match(r'^\\s*([a-z_]+)\\s*=',line)\n        if not match or match.group(1) not in changes:lines.append(line)\n    if lines and not lines[-1].endswith('\\n'):lines.append('\\n')\n    lines.append('\\n# Settings managed by PiNAS\\n')\n    for key,val in sorted(changes.items()):\n        if key=='media_dir':\n            for folder in val:lines.append('media_dir='+folder+'\\n')\n        elif val!='':lines.append(key+'='+val+'\\n')\n    try:\n        atomic(''.join(lines))\n        run(['/usr/bin/systemctl','restart','minidlna.service'])\n        if active()!='active':raise RuntimeError('MiniDLNA failed to start')\n    except Exception:\n        atomic(before)\n        try:run(['/usr/bin/systemctl','restart','minidlna.service'])\n        except Exception:pass\n        raise\n    status()\ndef main():\n    if os.geteuid()!=0:raise ValueError('Root required')\n    if len(sys.argv)!=2 or sys.argv[1] not in ('status','install','save','start','stop','restart','rescan'):raise ValueError('Unsupported command')\n    action=sys.argv[1]\n    if action=='status':status();return\n    if action=='install':\n        if not installed():\n            env=os.environ.copy();env.update({'PATH':'/usr/sbin:/usr/bin:/sbin:/bin','DEBIAN_FRONTEND':'noninteractive'})\n            run(['/usr/bin/apt-get','install','-y','--no-install-recommends','minidlna'],timeout=210,env=env)\n            run(['/usr/bin/systemctl','enable','--now','minidlna.service'])\n        status();return\n    if not installed():raise ValueError('MiniDLNA is not installed')\n    if action=='save':\n        raw=sys.stdin.read(16385)\n        if len(raw)>16384:raise ValueError('Request too large')\n        save(json.loads(raw));return\n    # Normal restart triggers scanning with the configured inotify watcher.\n    run(['/usr/bin/systemctl','restart' if action=='rescan' else action,'minidlna.service'])\n    status()\nif __name__=='__main__':\n    try:main()\n    except Exception as exc:print(str(exc),file=sys.stderr);sys.exit(1)\n"
